import {GROUPS,EQUIPMENT,GOALS,uid,localDate,dateAdd,defaultGroups,generate,minutes,parseLoad,newSession,validateBackup,candidates,resetPlan} from './core.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
let lib=[],db,state,view='train',step=0,draft=null,selectedDate=localDate(),saving=Promise.resolve(),scrolls={},editing=null,deferredInstall=null,restEnd=0,mediaObserver,offlineBusy=false;
const initial=()=>({schema:1,profile:null,plan:null,sessions:[],theme:localStorage.getItem('pf-theme')||'system'});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const exBy=id=>lib.find(e=>e.id===id),fmt=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long'}),short=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3600)}
function write(){let copy=structuredClone(state);$('.saving')?.replaceChildren(document.createTextNode('Salvando…'));saving=saving.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{let tx=db.transaction('data','readwrite');tx.objectStore('data').put(copy,'state');tx.oncomplete=()=>{if($('.saving'))$('.saving').textContent='Salvo neste aparelho';resolve()};tx.onerror=()=>{toast('Não foi possível salvar. Exporte um backup antes de sair.');reject(tx.error)}}));return saving}
function applyTheme(){localStorage.setItem('pf-theme',state.theme);document.documentElement.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme;document.querySelector('meta[name=theme-color]').content=document.documentElement.dataset.theme==='dark'?'#0d201d':'#f6f8f5'}
const icon=n=>({train:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 4h3m2 0h3"/>',history:'<path d="M4 10a8 8 0 1 1 0 5M4 4v6h6m2-4v6l4 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>'}[n]);
function header(){return `<header class="top"><div class="brand"><span class="brandmark" aria-hidden="true"></span>PersonFit</div><small>${state.plan?'SEU TREINO':'CONFIGURAÇÃO'}</small></header>`}
function nav(){return `<nav class="nav" aria-label="Principal">${[['train','Treino'],['history','Histórico'],['settings','Ajustes']].map(([id,t])=>`<button data-action="nav" data-id="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icon(id)}</svg>${t}</button>`).join('')}</nav>`}
function render(keep=true){if(view==='setup'&&draft)sessionStorage.setItem('pf-setup',JSON.stringify({draft,step}));let y=keep?window.scrollY:0;mediaObserver?.disconnect();app.innerHTML=header()+`<main class="shell">${view==='setup'?setup():view==='train'?train():view==='history'?history():settings()}</main>`+(view==='setup'?'':nav());observeVideos();requestAnimationFrame(()=>{window.scrollTo(0,y);$('.day.active')?.scrollIntoView({block:'nearest',inline:'center'})})}
function freshProfile(){return {goal:'',experience:'new',days:3,time:60,count:'auto',division:'movement',groups:defaultGroups(3),equipment:[],restrictions:'',excluded:[]}}
function beginSetup(profile){draft=structuredClone(profile||freshProfile());step=0;view='setup';render(false)}
function choice(value,title,desc,field){return `<button class="choice ${draft[field]===value?'selected':''}" data-action="choose" data-field="${field}" data-value="${value}" aria-pressed="${draft[field]===value}"><span class="radio" aria-hidden="true"></span><span><strong>${title}</strong><small>${desc}</small></span></button>`}
const options=(arr,value)=>arr.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('');
function setup(){let body='';
 if(step===0)body=`<div class="eyebrow">01 / 05 · Objetivo</div><h1>O que você quer priorizar?</h1><p class="muted">Escolha uma prioridade para o seu plano.</p><div class="choices space">${Object.entries(GOALS).map(([k,v])=>choice(k,...v,'goal')).join('')}</div>`;
 if(step===1)body=`<div class="eyebrow">02 / 05 · Rotina</div><h1>Como será sua semana?</h1><div class="space"><label class="field"><span>Experiência com musculação</span><select data-profile="experience">${options([['new','Estou começando ou retomando'],['regular','Já treino com regularidade'],['advanced','Tenho experiência avançada']],draft.experience)}</select></label><label class="field"><span>Dias disponíveis por semana</span><select data-profile="days">${options([1,2,3,4,5,6].map(n=>[n,n+' '+(n===1?'dia':'dias')]),draft.days)}</select></label><label class="field"><span>Tempo por sessão</span><select data-profile="time">${options([30,45,60,75,90].map(n=>[n,n+' minutos']),draft.time)}</select></label><label class="field"><span>Quantos exercícios por treino?</span><select data-profile="count">${options([['auto','Recomendado para mim'],...[3,4,5,6,7,8,9,10].map(n=>[n,n+' exercícios'])],draft.count)}</select><small>Apenas exercícios principais. O aquecimento fica separado. O resumo verifica se a quantidade cabe no seu tempo.</small></label></div>`;
 if(step===2)body=`<div class="eyebrow">03 / 05 · Divisão</div><h1>Como você prefere dividir os treinos?</h1><div class="choices space">${choice('movement','Por movimento','Empurrar, puxar e pernas, distribuídos nos dias disponíveis.','division')}${choice('muscle','Por grupo muscular','Escolha o foco de cada dia. Combine grupos quando precisar.','division')}</div>${draft.division==='movement'?`<div class="notice"><strong>Empurrar</strong>: peito, ombros e tríceps.<br><strong>Puxar</strong>: costas e bíceps.<br><strong>Pernas</strong>: membros inferiores.${draft.days<3?'<br>Com 1 ou 2 dias, os movimentos se combinam em corpo inteiro ou superiores e pernas.':''}</div>`:groupEditor()} `;
 if(step===3)body=`<div class="eyebrow">04 / 05 · Equipamentos</div><h1>O que está disponível?</h1><p class="muted">Selecione os equipamentos que você pode usar.</p><div class="chips">${EQUIPMENT.map(e=>`<button class="chip ${draft.equipment.includes(e)?'selected':''}" data-action="equipment" data-id="${e}" aria-pressed="${draft.equipment.includes(e)}">${e[0].toUpperCase()+e.slice(1)}</button>`).join('')}</div><div class="notice">Para barras e halteres, considere também banco e suportes adequados. A biblioteca atual não cobre treino completo só com peso corporal.</div><label class="field space"><span>Restrições ou observações (opcional)</span><textarea data-profile="restrictions" maxlength="1000" placeholder="Movimentos que você precisa evitar…">${esc(draft.restrictions)}</textarea><small>Esta anotação não faz uma avaliação clínica. Exclua abaixo os exercícios que não devem entrar no plano e revise restrições com um profissional.</small></label><details><summary>Excluir exercícios do plano</summary><div class="stack">${lib.map(e=>`<label class="checklabel"><input type="checkbox" data-exclude="${e.id}" ${draft.excluded.includes(e.id)?'checked':''}>${esc(e.name)}</label>`).join('')}</div></details>`;
 if(step===4){let result,error;try{result=generate(draft,lib)}catch(e){error=e.message}body=`<div class="eyebrow">05 / 05 · Revisão</div><h1>Confira seu plano.</h1><p class="muted">Você pode ajustar tudo antes de começar.</p>${[['Objetivo',GOALS[draft.goal]?.[0],0],['Rotina',`${draft.days} dias · ${draft.time} min · ${draft.count==='auto'?'quantidade recomendada':draft.count+' exercícios'} · ${{new:'começando ou retomando',regular:'treino regular',advanced:'experiência avançada'}[draft.experience]}`,1],['Divisão',draft.division==='movement'?'Por movimento':'Por grupo muscular',2],['Equipamentos',draft.equipment.join(', ')||'Nenhum selecionado',3]].map(([a,b,n])=>`<div class="summaryrow"><div><strong>${a}</strong><span>${esc(b)}</span></div><button class="quiet" data-action="step" data-id="${n}">Editar</button></div>`).join('')}${draft.restrictions?`<p class="notice">Sua observação: ${esc(draft.restrictions)}<br>Confira as exclusões escolhidas. O texto acima não altera exercícios automaticamente.</p>`:''}${error?`<p class="notice error" role="alert">${esc(error)}</p><button data-action="step" data-id="1">Ajustar tempo ou quantidade</button>`:`<div class="space stack">${result.templates.map(t=>`<div><strong>${esc(t.name)}</strong><p class="muted">${t.exercises.length} exercícios · cerca de ${t.duration} min</p></div>`).join('')}</div><p class="notice">4 semanas a partir de ${fmt(localDate())}. Exercícios estáveis durante o plano, com dias de descanso. A carga é sempre registrada por você.</p>`}${draft.excluded.length?`<details><summary>${draft.excluded.length} exercícios excluídos</summary><p class="muted">${draft.excluded.map(id=>esc(exBy(id).name)).join(', ')}</p></details>`:''}<p class="muted space">O plano é uma sugestão e pode ser revisado por um profissional.</p>`;}
 return `<div class="hero"><div class="steps" aria-label="Etapa ${step+1} de 5">${[0,1,2,3,4].map(n=>`<span class="${n<=step?'filled':''}"></span>`).join('')}</div>${body}<div id="setup-error" role="alert"></div><div class="stepfoot"><button class="quiet" data-action="${step?'back':'setupExit'}">${step?'Voltar':'Ajustes'}</button><button class="primary" data-action="${step===4?'create':'next'}" ${step===0&&!draft.goal?'disabled':''}>${step===4?'Criar meu plano':'Continuar'}${step===4?'':' →'}</button></div></div>`;
}
function groupEditor(){let missing=GROUPS.filter(g=>!draft.groups.flat().includes(g));return `<div class="space stack">${draft.groups.map((gs,i)=>`<div class="card"><h3>Dia ${i+1}</h3><div class="chips">${GROUPS.map(g=>`<button data-action="group" data-day="${i}" data-id="${g}" class="chip ${gs.includes(g)?'selected':''}" aria-pressed="${gs.includes(g)}">${g}</button>`).join('')}</div></div>`).join('')}</div>${missing.length?`<div class="notice error">Faltam: ${missing.join(', ')}. Combine esses grupos em algum dia.<button class="quiet" data-action="suggestGroups">Restaurar sugestão</button></div>`:''}`}
function current(){let p=state.plan,day=p?.calendar.find(d=>d.date===selectedDate),template=p?.templates.find(t=>t.id===day?.templateId),session=state.sessions.find(s=>s.planId===p?.id&&s.date===selectedDate);return {p,day,template,session}}
function ensureSession(){let c=current();if(!c.template)return; if(!c.session){c.session=newSession(c.p,c.day,c.template);state.sessions.push(c.session);write()}return c.session}
function previous(id){return state.sessions.filter(s=>s.finishedAt&&s.date<=selectedDate&&s.id!==current().session?.id).sort((a,b)=>b.date.localeCompare(a.date)||b.finishedAt.localeCompare(a.finishedAt)).flatMap(s=>s.exercises).find(e=>e.id===id&&(e.load!==''||e.bodyweight||e.setsLoads.some(v=>v!=='')))}
function train(){if(!state.plan)return `<div class="hero"><div class="eyebrow">Seu plano</div><h1>Vamos organizar seus treinos.</h1><p class="muted">Escolha sua rotina, equipamentos e divisão.</p><button class="primary space" data-action="new">Criar plano</button></div>`;
 if(!state.plan.calendar.some(d=>d.date===selectedDate)){selectedDate=state.plan.calendar.find(d=>d.date>=localDate()&&d.templateId)?.date||state.plan.calendar[0].date}
 let {p,day,template,session}=current(),rows=session?.exercises||template?.exercises||[],done=rows.filter(e=>e.done).length,active=state.sessions.find(s=>s.startedAt&&!s.finishedAt&&s.date!==selectedDate),week=Math.floor(p.calendar.findIndex(d=>d.date===selectedDate)/7)+1;
 return `<div class="hero"><div class="row"><div><div class="eyebrow">${new Date(selectedDate+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</div><h1>Seu treino</h1></div><span class="pill">Semana ${week} / 4</span></div></div>${active?`<div class="notice row"><span>Há um treino em andamento em ${short(active.date)}.</span><button data-action="resume" data-id="${active.date}">Retomar</button></div>`:''}<div class="days" aria-label="Dias do plano">${p.calendar.map(d=>`<button data-action="date" data-id="${d.date}" class="day ${d.date===selectedDate?'active':''} ${!d.templateId?'rest':''}" ${d.date===selectedDate?'aria-current="date"':''} aria-label="${fmt(d.date)}${d.templateId?' treino':' descanso'}">${new Date(d.date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}<strong>${Number(d.date.slice(-2))}</strong><span class="dot" style="${d.templateId?'':'visibility:hidden'}"></span></button>`).join('')}</div>${!template?`<div class="empty"><div class="eyebrow">${fmt(selectedDate)}</div><h2>Dia de descanso</h2><p>Seu próximo treino está no seletor de dias.</p></div>`:`<div class="workhead row"><div><h2>${esc(session?.name||template.name)}</h2><span class="muted">${fmt(selectedDate)} · ${minutes(rows)} min estimados</span></div><span class="count">${done} de ${rows.length}</span></div><div class="progress" role="progressbar" aria-label="Exercícios concluídos" aria-valuemin="0" aria-valuemax="${rows.length}" aria-valuenow="${done}"><div style="width:${done/rows.length*100}%"></div></div><details class="section" style="padding:0 0 12px;border:0"><summary>Aquecimento · separado do treino</summary><p class="muted">Reserve cerca de 5 min para movimento leve e preparação dos movimentos do dia. Séries de aproximação não entram na contagem abaixo.</p></details>${!session?.finishedAt?`<div class="workactions"><button data-action="${session?.startedAt?'finish':'start'}" class="primary">${session?.startedAt?'Finalizar treino':'Iniciar treino'}</button>${session?.startedAt?'<button data-action="timer" class="timer" data-timer>Descanso</button>':''}</div>`:''}${rows.map((e,i)=>exerciseRow(e,i,session)).join('')}<div class="workactions">${session?.finishedAt?`<div class="notice" style="width:100%;margin:0">Treino ${done===rows.length?'concluído':'parcial'} salvo. <button class="quiet" data-action="historySession" data-id="${session.id}">Ver registro</button></div>`:`<button data-action="${session?.startedAt?'finish':'start'}" class="primary">${session?.startedAt?'Finalizar treino':'Iniciar treino'}</button>${session?.startedAt?`<button data-action="timer" class="timer" data-timer>Descanso</button>`:''}`}</div><div class="row"><button class="quiet" data-action="editDay" data-id="${template.id}">Editar este treino</button><span class="saving">Salvo neste aparelho</span></div>`}<p class="muted space">Sugestão de plano. Pode ser revisada por um profissional.</p>`;
}
function exerciseRow(e,i,session){let data=exBy(e.id),prev=previous(e.id),locked=!!session?.finishedAt,load=e.load??'';return `<article class="exercise ${e.done?'completed':''}"><div class="exrow"><button class="thumb" data-action="media" data-id="${e.id}" aria-label="Ver demonstração de ${esc(data.name)}"><video muted loop playsinline preload="none" poster="./${data.poster}" data-src="./${data.media}"></video><span class="playmark">▶</span></button><div><h3 class="exname">${esc(data.name)}</h3><div class="exmeta">${e.sets} séries × ${esc(e.reps)} rep.<br>${e.rest}s de descanso</div></div><button class="done ${e.done?'checked':''}" data-action="done" data-index="${i}" aria-label="${e.done?'Desmarcar':'Concluir'} ${esc(data.name)}" aria-pressed="${!!e.done}" ${locked?'disabled':''}>${e.done?'✓':'○'}</button></div><div class="loadrow"><label class="loadfield"><input inputmode="decimal" type="text" autocomplete="off" value="${load}" data-load="${i}" aria-label="Carga em kg, ${esc(data.name)}" placeholder="—" ${locked||e.bodyweight?'disabled':''}><span>kg${data.equipment==='halteres'?'<br><small>por halter</small>':''}</span></label>${prev?`<div class="previous">Última: ${prev.bodyweight?'peso corporal':prev.load!==''?prev.load+' kg':'por série'}${!locked?`<br><button class="reuse" data-action="reuse" data-index="${i}">Usar anterior</button>`:''}</div>`:'<small>Sem carga anterior</small>'}</div><details><summary>Cargas por série e opções</summary><label class="checklabel"><input type="checkbox" data-body="${i}" ${e.bodyweight?'checked':''} ${locked?'disabled':''}>Peso corporal</label><div class="sets">${Array.from({length:e.sets},(_,j)=>`<label class="setrow"><span>Série ${j+1}</span><input type="text" inputmode="decimal" autocomplete="off" data-set="${i}:${j}" value="${e.setsLoads?.[j]??''}" placeholder="—" aria-label="Carga série ${j+1} de ${esc(data.name)}" ${locked||e.bodyweight?'disabled':''}><span>kg</span></label>`).join('')}</div><small>Vazio significa não registrado; 0 é uma carga registrada. Se preencher séries, elas prevalecem no histórico.</small>${!locked?`<br><button class="quiet" data-action="swap" data-index="${i}">Substituir exercício</button>`:''}</details></article>`}
function history(){let sessions=state.sessions.filter(s=>s.finishedAt).sort((a,b)=>b.date.localeCompare(a.date));let ids=[...new Set(sessions.flatMap(s=>s.exercises.map(e=>e.id)))];return `<div class="hero"><div class="eyebrow">Registros</div><h1>Histórico</h1><p class="muted">Seus treinos e as cargas que você registrou.</p></div>${sessions.length?`<label class="field"><span>Evolução por exercício</span><select id="evolution"><option value="">Selecione um exercício</option>${ids.map(id=>`<option value="${id}">${esc(exBy(id).name)}</option>`).join('')}</select></label><div id="evolution-results"></div><div class="section"><h3>Sessões · ${sessions.length}</h3>${sessions.map(s=>`<button class="historyitem" data-action="historySession" data-id="${s.id}"><div class="row"><strong>${esc(s.name)}</strong><span class="muted">↗</span></div><small>${fmt(s.date)} · ${s.exercises.filter(e=>e.done).length}/${s.exercises.length} concluídos${s.exercises.every(e=>e.done)?'':' · parcial'}</small></button>`).join('')}</div>`:`<div class="empty"><h2>Nenhum treino salvo ainda</h2><p>Finalize sua primeira sessão para consultar os registros.</p><button data-action="nav" data-id="train">Ir para o treino</button></div>`}`}
function settings(){return `<div class="hero"><div class="eyebrow">Preferências</div><h1>Ajustes</h1></div><div class="settingrow"><div><strong>Aparência</strong><small>Acompanhe o aparelho ou escolha um tema.</small></div><select id="theme" aria-label="Tema">${options([['system','Sistema'],['light','Claro'],['dark','Escuro']],state.theme)}</select></div><div class="section"><h3>Perfil e plano</h3>${state.profile?`<p class="muted">${esc(GOALS[state.profile.goal]?.[0])} · ${state.profile.days} dias/semana<br>${state.profile.time} min · ${state.profile.division==='movement'?'Por movimento':'Por grupo muscular'}</p>${state.profile.restrictions?`<p class="notice">Observações: ${esc(state.profile.restrictions)}</p>`:''}`:'<p class="muted">Você ainda não criou um perfil.</p>'}<div class="settingsactions">${state.plan?`<button data-action="plan">Editar exercícios do plano</button><button data-action="reset" class="danger">Apagar plano e começar de novo</button>`:`<button data-action="new">Criar plano</button>`}<button data-action="profile">Consultar perfil</button></div></div><div class="section"><h3>Conteúdo offline</h3><p class="muted">Baixe apenas as demonstrações do seu plano atual.</p><p class="muted" id="offline-status">Verificando conteúdo…</p><button data-action="offline" id="offline-btn" ${!state.plan||offlineBusy?'disabled':''}>${offlineBusy?'Baixando…':'Preparar plano offline'}</button><div class="installtip space">${deferredInstall?'<button data-action="install">Instalar PersonFit</button>':'No iPhone: Safari → Compartilhar → Adicionar à Tela de Início. No Android: menu do Chrome → Instalar aplicativo.'}</div><div id="update-area"></div></div><div class="section"><h3>Dados e backup</h3><p class="muted">Os dados ficam neste navegador e dispositivo, sem sincronização automática.</p><div class="settingsactions"><button data-action="export">Exportar backup JSON</button><button data-action="import">Importar backup JSON</button><input type="file" id="backup-file" accept="application/json,.json" hidden><button data-action="wipe" class="danger">Apagar todos os dados</button></div></div><div class="section"><h3>Sobre o PersonFit</h3><p class="muted">Biblioteca com ${lib.length} exercícios e vídeos locais. Demonstrações por Goulart / wger, CC BY-SA 4.0.</p><button class="quiet" data-action="credits">Fontes e licenças</button></div>`}
function show(html){document.querySelectorAll('video').forEach(v=>v.pause());modal.innerHTML=`<button class="close" data-action="close" aria-label="Fechar">×</button>`+html;modal.showModal()}
function close(){modal.querySelectorAll('video').forEach(v=>v.pause());modal.close();modal.innerHTML='';observeVideos()}
modal.addEventListener('cancel',e=>{e.preventDefault();close()});
function observeVideos(){mediaObserver?.disconnect();mediaObserver=new IntersectionObserver(entries=>{for(let {target:v,isIntersecting} of entries){if(!isIntersecting||document.hidden||modal.open){v.pause();continue}if(!v.src)v.src=v.dataset.src;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)v.play().catch(()=>{})}},{threshold:.2});document.querySelectorAll('video[data-src]').forEach(v=>mediaObserver.observe(v));if(view==='settings'){checkOffline();showUpdate()}}
function showMedia(id){let e=exBy(id);show(`<div class="eyebrow">Demonstração</div><h2>${esc(e.name)}</h2><video id="demo" src="./${e.media}" poster="./${e.poster}" loop playsinline muted controls preload="metadata"></video><button class="quiet" data-action="playPause">Reproduzir / pausar</button><ol>${e.instructions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><details><summary>Fonte e licença</summary><p class="muted">${esc(e.author)} · <a href="${e.source}" target="_blank" rel="noopener">wger</a> · <a href="${e.licenseUrl}" target="_blank" rel="noopener">${e.license}</a><br>${esc(e.mediaChanges)}</p></details>`);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#demo').play().catch(()=>{})}
function record(s){show(`<div class="eyebrow">${fmt(s.date)}</div><h2>${esc(s.name)}</h2><p class="muted">${s.exercises.filter(e=>e.done).length} de ${s.exercises.length} exercícios concluídos</p>${s.exercises.map(e=>`<div class="section" style="padding:14px 0"><h3>${e.done?'✓':'○'} ${esc(exBy(e.id).name)}</h3><p class="muted">${e.sets} × ${esc(e.reps)} · ${e.rest}s de descanso<br>${loadDescription(e)}</p></div>`).join('')}`)}
function loadDescription(e){if(e.bodyweight)return 'Peso corporal';if(e.setsLoads?.some(n=>n!==''))return e.setsLoads.map((n,i)=>`S${i+1}: ${n===''?'não registrada':esc(n)+' kg'}`).join(' · ');return e.load!==''&&e.load!=null?esc(e.load)+' kg'+(exBy(e.id).equipment==='halteres'?' por halter':''):'Carga não registrada'}
function sessionChanged(){write();let y=scrollY;render();window.scrollTo(0,y)}
function editDay(id){let t=state.plan.templates.find(t=>t.id===id);editing=structuredClone(t);editDialog()}
function editDialog(){let pool=candidates(state.profile,lib);showEdit(`<div class="eyebrow">Editar plano</div><h2>${esc(editing.name)}</h2><p class="muted">Altera as próximas sessões deste treino. Sessões já iniciadas ou finalizadas mantêm seu registro.</p>${editing.exercises.map((e,i)=>`<div class="editex"><label class="field" style="margin-bottom:5px"><span>Exercício ${i+1}</span><select data-edit-select="${i}">${pool.filter(a=>a.id===e.id||!editing.exercises.some(b=>b.id===a.id)).map(a=>`<option value="${a.id}" ${a.id===e.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div class="editgrid"><label>Séries<input data-edit="${i}:sets" type="number" min="1" max="8" value="${e.sets}"></label><label>Repetições<input data-edit="${i}:reps" value="${esc(e.reps)}" inputmode="text" maxlength="5"></label><label>Descanso (s)<input data-edit="${i}:rest" type="number" min="15" max="600" value="${e.rest}"></label></div><div class="row"><button class="quiet" data-action="moveEx" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Mover para cima">↑</button><button class="quiet" data-action="moveEx" data-index="${i}" data-direction="1" ${i===editing.exercises.length-1?'disabled':''} aria-label="Mover para baixo">↓</button><button class="quiet danger" data-action="removeEx" data-index="${i}" ${editing.exercises.length<=3?'disabled':''}>Remover</button></div></div>`).join('')}<p class="muted space">${editing.exercises.length} exercícios · cerca de ${minutes(editing.exercises)} min</p><p class="muted">Cobertura do dia: ${[...new Set(editing.exercises.map(e=>exBy(e.id).group))].join(', ')}</p><button data-action="addEx" ${editing.exercises.length>=10?'disabled':''}>Adicionar exercício</button><div id="edit-error" role="alert"></div><div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-action="saveEdit">Salvar alterações</button></div>`)}
function showEdit(s){if(modal.open){let pos=modal.scrollTop;modal.innerHTML='<button class="close" data-action="close" aria-label="Fechar">×</button>'+s;modal.scrollTop=pos}else show(s)}
const actions={
 nav:b=>{scrolls[view]=scrollY;view=b.dataset.id;render(false);requestAnimationFrame(()=>scrollTo(0,scrolls[view]||0))},
 new:()=>beginSetup(state.profile),setupExit:()=>{view='settings';render(false)},
 choose:b=>{draft[b.dataset.field]=b.dataset.value;render()},equipment:b=>{let a=draft.equipment,i=a.indexOf(b.dataset.id);i<0?a.push(b.dataset.id):a.splice(i,1);render()},
 group:b=>{let a=draft.groups[+b.dataset.day],i=a.indexOf(b.dataset.id);i<0?a.push(b.dataset.id):a.splice(i,1);render()},suggestGroups:()=>{draft.groups=defaultGroups(draft.days);render()},
 next:()=>{step++;render(false)},back:()=>{step--;render(false)},step:b=>{step=+b.dataset.id;render(false)},
 create:async()=>{try{let plan=generate(draft,lib);state.profile=structuredClone(draft);state.plan=plan;await write();sessionStorage.removeItem('pf-setup');view='train';selectedDate=localDate();render(false)}catch(e){$('#setup-error').innerHTML=`<p class="notice error">${esc(e.message)}</p>`}},
 date:b=>{selectedDate=b.dataset.id;render()},resume:b=>{selectedDate=b.dataset.id;view='train';render(false)},
 media:b=>showMedia(b.dataset.id),close,playPause:()=>{let v=$('#demo');v.paused?v.play():v.pause()},
 start:()=>{let active=state.sessions.find(s=>s.startedAt&&!s.finishedAt&&s.date!==selectedDate);if(active){toast('Retome e finalize a sessão em andamento primeiro.');return}let s=ensureSession();if(s.finishedAt)return;s.startedAt=new Date().toISOString();sessionChanged()},
 done:b=>{let s=ensureSession();if(!s||s.finishedAt)return;s.exercises[+b.dataset.index].done=!s.exercises[+b.dataset.index].done;sessionChanged()},
 reuse:b=>{let s=ensureSession(),e=s.exercises[+b.dataset.index],p=previous(e.id);if(p){e.load=p.load;e.bodyweight=p.bodyweight;e.setsLoads=Array.from({length:e.sets},(_,i)=>p.setsLoads?.[i]??'');sessionChanged();toast('Carga anterior aplicada a esta sessão.')}},
 finish:()=>{let s=current().session,done=s.exercises.filter(e=>e.done).length;show(`<h2>${done===s.exercises.length?'Finalizar treino?':'Salvar treino parcial?'}</h2><p>${done} de ${s.exercises.length} exercícios concluídos. Os exercícios pendentes continuarão identificados no registro.</p><div class="modalfoot"><button data-action="close">Continuar treino</button><button class="primary" data-action="confirmFinish">Salvar ${done===s.exercises.length?'treino':'parcial'}</button></div>`)},
 confirmFinish:async()=>{let s=current().session;s.finishedAt=new Date().toISOString();restEnd=0;await write();close();render();toast('Treino salvo no histórico.')},
 timer:()=>show(`<h2>Descanso</h2><p class="muted">O cronômetro segue pelo horário, mesmo ao trocar de aplicativo.</p><div class="chips">${[45,60,75,90,120,180].map(s=>`<button data-action="startTimer" data-id="${s}">${s}s</button>`).join('')}</div><button class="quiet space" data-action="stopTimer">Encerrar descanso</button>`),
 startTimer:b=>{restEnd=Date.now()+Number(b.dataset.id)*1000;sessionStorage.setItem('pf-rest',restEnd);close();tick()},stopTimer:()=>{restEnd=0;sessionStorage.removeItem('pf-rest');close();tick()},
 swap:b=>{let s=ensureSession(),i=+b.dataset.index,e=exBy(s.exercises[i].id),pool=candidates(state.profile,lib).filter(a=>e.alternatives.includes(a.id)&&!s.exercises.some(x=>x.id===a.id));show(`<h2>Substituir exercício</h2><p class="muted">Variação do mesmo movimento, com os seus equipamentos. Confira a técnica e a carga ao trocar.</p><div class="stack">${pool.map(a=>`<button data-action="swapTo" data-index="${i}" data-id="${a.id}">${esc(a.name)}<br><small>${a.equipment}</small></button>`).join('')||'<p>Nenhuma alternativa disponível com os filtros atuais.</p>'}</div>`)},
 swapTo:b=>{let s=ensureSession(),i=+b.dataset.index,e=s.exercises[i];s.exercises[i]={...e,id:b.dataset.id,load:'',bodyweight:false,setsLoads:Array(e.sets).fill(''),done:false};close();sessionChanged()},
 historySession:b=>record(state.sessions.find(s=>s.id===b.dataset.id)),
 plan:()=>show(`<h2>Editar plano</h2><div class="stack">${state.plan.templates.map(t=>`<button data-action="editDay" data-id="${t.id}">${esc(t.name)}<br><small>${t.exercises.length} exercícios</small></button>`).join('')}</div>`),editDay:b=>{close();editDay(b.dataset.id)},
 moveEx:b=>{let i=+b.dataset.index,j=i+(+b.dataset.direction);[editing.exercises[i],editing.exercises[j]]=[editing.exercises[j],editing.exercises[i]];editDialog()},
 removeEx:b=>{editing.exercises.splice(+b.dataset.index,1);editDialog()},
 addEx:()=>{let e=candidates(state.profile,lib).find(e=>editing.groups.includes(e.group)&&!editing.exercises.some(x=>x.id===e.id));if(!e){toast('Não há outro exercício compatível para este dia.');return}editing.exercises.push({...editing.exercises[0],id:e.id});editDialog()},
 saveEdit:async()=>{let err='';if(editing.exercises.some(e=>!Number.isInteger(e.sets)||e.sets<1||e.sets>8||!/^\d{1,2}(?:[–-]\d{1,2})?$/.test(e.reps)||e.reps.match(/\d+/g).some(n=>+n<1||+n>50)||e.rest<15||e.rest>600))err='Use 1 a 8 séries, 1 a 50 repetições (ex.: 8–12) e 15 a 600 segundos.';else if(minutes(editing.exercises)>state.profile.time)err=`Este treino leva cerca de ${minutes(editing.exercises)} min. Reduza a quantidade, séries ou repetições para caber em ${state.profile.time} min.`;else{let all=state.plan.templates.flatMap(t=>t.id===editing.id?editing.exercises:t.exercises),missing=GROUPS.filter(g=>!all.some(e=>exBy(e.id).group===g));if(missing.length)err='A edição deixaria sem exercícios: '+missing.join(', ')+'. Ajuste a distribuição antes de salvar.'}if(err){$('#edit-error').innerHTML=`<p class="notice error">${esc(err)}</p>`;return}editing.duration=minutes(editing.exercises);state.plan.templates=state.plan.templates.map(t=>t.id===editing.id?editing:t);state.plan.version++;await write();close();render();toast('Plano atualizado. Registros anteriores preservados.')},
 profile:()=>show(`<h2>Seu perfil</h2>${state.profile?`<p>${esc(GOALS[state.profile.goal]?.[0])}</p><p class="muted">Experiência: ${{new:'começando ou retomando',regular:'regular',advanced:'avançada'}[state.profile.experience]}<br>${state.profile.days} dias por semana · ${state.profile.time} minutos<br>Exercícios: ${state.profile.count==='auto'?'recomendado':state.profile.count}<br>Equipamentos: ${esc(state.profile.equipment.join(', '))}</p><p class="muted">Para refazer a rotina, use “Apagar plano e começar de novo”. O histórico concluído é preservado.</p>`:'<p>Crie seu plano para definir o perfil.</p>'}`),
 reset:()=>{let active=state.sessions.some(s=>!s.finishedAt&&s.planId===state.plan.id);show(`<h2>Apagar plano e começar de novo?</h2><p>O plano atual será removido e a configuração será reaberta. Seu histórico de treinos concluídos será preservado.</p>${active?'<p class="notice error">Há uma sessão não finalizada. Seu progresso será removido.</p>':''}<label class="checklabel"><input type="checkbox" id="reuse-profile" checked>Reutilizar os dados do perfil</label><div class="modalfoot"><button data-action="close">Cancelar</button><button class="danger" data-action="confirmReset">Apagar plano</button></div>`)},
 confirmReset:async()=>{let p=$('#reuse-profile').checked?state.profile:null;state=resetPlan(state,!!p);restEnd=0;sessionStorage.removeItem('pf-rest');await write();close();beginSetup(p)},
 wipe:()=>show(`<h2>Apagar todos os dados?</h2><p>Remove perfil, plano, histórico e preferências deste navegador. Esta ação não pode ser desfeita.</p><label class="checklabel"><input type="checkbox" id="wipe-check">Entendo que também perderei o histórico</label><div class="modalfoot"><button data-action="close">Cancelar</button><button class="danger" data-action="confirmWipe">Apagar todos os dados</button></div>`),
 confirmWipe:async()=>{if(!$('#wipe-check').checked){toast('Confirme que deseja remover também o histórico.');return}state=initial();state.theme='system';restEnd=0;['pf-rest','pf-setup'].forEach(k=>sessionStorage.removeItem(k));await write();applyTheme();close();beginSetup(null)},
 export:async()=>{await saving;let blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`personfit-backup-${localDate()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000)},
 import:()=>$('#backup-file').click(),
 confirmImport:async()=>{state=actions.pendingImport;restEnd=0;sessionStorage.removeItem('pf-rest');sessionStorage.removeItem('pf-setup');delete actions.pendingImport;await write();applyTheme();close();view=state.plan?'train':'settings';selectedDate=localDate();render(false);toast('Backup importado.')},
 offline:()=>prepareOffline(),install:async()=>{await deferredInstall?.prompt();deferredInstall=null;render()},
 credits:()=>show(`<h2>Fontes e licenças</h2><p class="muted">Código PersonFit: MIT. Vídeos: Goulart via wger, CC BY-SA 4.0. Transcodificados para H.264, sem áudio, até 22 s. Instruções em português e seleção adaptadas para o PersonFit; dados derivados mantêm a licença original de cada entrada.</p><p><a href="./ATTRIBUTIONS.md" target="_blank">Atribuições completas, por exercício</a></p><p><a href="https://github.com/wger-project/wger" target="_blank" rel="noopener">Repositório wger (AGPL-3.0)</a></p><p class="muted">Nenhum código do aplicativo wger foi copiado. As regras locais do PersonFit não são validadas clinicamente pelo catálogo.</p>`),
 update:()=>{if(state.sessions.some(s=>s.startedAt&&!s.finishedAt)){toast('Finalize a sessão antes de atualizar.');return}navigator.serviceWorker.getRegistration('./').then(r=>r?.waiting?.postMessage({type:'ACTIVATE'}))}
};
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b&&!b.disabled){Promise.resolve(actions[b.dataset.action]?.(b)).catch(err=>{console.error(err);toast('Não foi possível concluir. Seus registros anteriores foram mantidos.')})}});
document.addEventListener('input',e=>{let t=e.target;if(t.matches('[data-profile=restrictions]')){draft.restrictions=t.value;sessionStorage.setItem('pf-setup',JSON.stringify({draft,step}))};if(t.hasAttribute('data-load')||t.hasAttribute('data-set')){let s=ensureSession();if(!s||s.finishedAt)return;try{let n=parseLoad(t.value);t.setCustomValidity('');t.style.borderColor='';if(t.hasAttribute('data-load'))s.exercises[+t.dataset.load].load=n;else{let [i,j]=t.dataset.set.split(':').map(Number);s.exercises[i].setsLoads[j]=n}write()}catch(err){t.setCustomValidity(err.message);t.reportValidity();t.style.borderColor='var(--danger)'}}if(t.dataset.edit){let [i,k]=t.dataset.edit.split(':');editing.exercises[+i][k]=k==='reps'?t.value:Number(t.value)}});
document.addEventListener('change',async e=>{let t=e.target;if(t.dataset.profile){let f=t.dataset.profile;draft[f]=['days','time'].includes(f)?Number(t.value):t.value;if(f==='days')draft.groups=defaultGroups(draft.days);sessionStorage.setItem('pf-setup',JSON.stringify({draft,step}))}if(t.dataset.exclude){let i=draft.excluded.indexOf(t.dataset.exclude);t.checked?draft.excluded.push(t.dataset.exclude):draft.excluded.splice(i,1)}if(t.dataset.body){let s=ensureSession();s.exercises[+t.dataset.body].bodyweight=t.checked;sessionChanged()}if(t.dataset.editSelect){editing.exercises[+t.dataset.editSelect].id=t.value;editDialog()}if(t.id==='theme'){state.theme=t.value;applyTheme();write()}if(t.id==='evolution'){let id=t.value;$('#evolution-results').innerHTML=id?state.sessions.filter(s=>s.finishedAt&&s.exercises.some(e=>e.id===id)).sort((a,b)=>a.date.localeCompare(b.date)).map(s=>{let e=s.exercises.find(e=>e.id===id);return `<div class="summaryrow"><span>${fmt(s.date)}${e.done?' · ✓':' · pendente'}</span><span>${loadDescription(e)}</span></div>`}).join(''):''}if(t.id==='backup-file'&&t.files[0]){try{if(t.files[0].size>10000000)throw Error('Arquivo muito grande (máximo 10 MB).');let b=validateBackup(JSON.parse(await t.files[0].text()),lib);actions.pendingImport=b;show(`<h2>Substituir os dados atuais?</h2><p>Este backup contém ${b.sessions.filter(s=>s.finishedAt).length} treinos concluídos${b.plan?' e um plano ativo':''}. A importação substitui os dados deste navegador.</p><p class="muted">Exporte um backup atual antes de continuar, se quiser preservá-lo.</p><div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-action="confirmImport">Substituir e importar</button></div>`)}catch(err){toast(err.message)}t.value=''}});
document.addEventListener('focusin',e=>{if(e.target.matches('input,textarea'))e.target.scrollIntoView({block:'nearest',behavior:'auto'})});
document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause());else{observeVideos();tick()}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state?.theme==='system')applyTheme()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(view==='settings')render()});
function tick(){let n=Math.max(0,Math.ceil((restEnd-Date.now())/1000));document.querySelectorAll('[data-timer]').forEach(t=>t.textContent=n?`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`:restEnd?'Descanso encerrado':'Descanso');if(restEnd&&n===0){restEnd=0;sessionStorage.removeItem('pf-rest')}}setInterval(tick,1000);
function requiredMedia(){let rows=[...(state.plan?.templates||[]),...state.sessions.filter(s=>!s.finishedAt&&s.planId===state.plan?.id)];return [...new Set(rows.flatMap(t=>t.exercises.flatMap(e=>{let d=exBy(e.id);return [d.media,d.poster]})))]}
async function checkOffline(){let node=$('#offline-status');if(!node||offlineBusy)return;if(!('serviceWorker'in navigator)||!('caches'in window)){node.textContent='Offline indisponível neste navegador. Abra em HTTPS ou localhost.';let b=$('#offline-btn');if(b)b.disabled=true;return}try{let ready=await navigator.serviceWorker.ready,cache=await caches.open('personfit-media-v1'),files=requiredMedia(),shell=await caches.open('personfit-shell-v1'),shellFiles=['./','./index.html','./app.js','./core.js','./style.css','./library.json','./manifest.webmanifest','./icon-192.png','./icon-512.png'],matches=await Promise.all([...files.map(f=>cache.match(new URL(f,location.href))),...shellFiles.map(f=>shell.match(new URL(f,location.href)))]);let n=matches.filter(r=>r?.ok).length;node.textContent=!state.plan?'Crie um plano para preparar o conteúdo.':n===files.length+shellFiles.length?'Pronto para usar offline':`${matches.slice(0,files.length).filter(r=>r?.ok).length} de ${files.length} arquivos do plano disponíveis. Prepare para verificar todos.`}catch{node.textContent='Não foi possível verificar o conteúdo offline.'}}
async function prepareOffline(){if(offlineBusy||!state.plan)return;offlineBusy=true;let btn=$('#offline-btn'),status=$('#offline-status');if(btn)btn.disabled=true;try{await navigator.serviceWorker.ready;let cache=await caches.open('personfit-media-v1'),files=requiredMedia(),failed=[];for(let i=0;i<files.length;i++){if(status?.isConnected)status.textContent=`Baixando e verificando ${i+1} de ${files.length}…`;try{let u=new URL(files[i],location.href),r=await fetch(u,{cache:'reload'});if(!r.ok)throw Error();await cache.put(u,r);if(!(await cache.match(u))?.ok)throw Error()}catch{failed.push(files[i])}}toast(failed.length?`${failed.length} arquivos falharam. Toque em preparar para tentar novamente.`:'Conteúdo do plano verificado.')}catch{toast('Não foi possível preparar. Abra em HTTPS com internet e tente novamente.')}finally{offlineBusy=false;if(view==='settings'){if(btn?.isConnected)btn.disabled=false;checkOffline()}}}
function showUpdate(){navigator.serviceWorker?.getRegistration('./').then(r=>{let a=$('#update-area');if(a&&r?.waiting)a.innerHTML='<p class="notice">Nova versão disponível. <button data-action="update">Atualizar após o treino</button></p>'})}
async function init(){try{lib=await (await fetch('./library.json')).json();db=await new Promise((resolve,reject)=>{let r=indexedDB.open('personfit',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});state=await new Promise((resolve,reject)=>{let r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result||initial());r.onerror=()=>reject(r.error)});applyTheme();restEnd=Number(sessionStorage.getItem('pf-rest')||0);let active=state.sessions.find(s=>s.startedAt&&!s.finishedAt);if(active)selectedDate=active.date;if(!state.plan){let stored;try{stored=JSON.parse(sessionStorage.getItem('pf-setup'))}catch{}if(stored?.draft){draft=stored.draft;step=Math.max(0,Math.min(4,stored.step));view='setup';render(false)}else beginSetup(state.profile)}else render(false);if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(r=>{r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',showUpdate));showUpdate()}).catch(()=>toast('O modo offline não pôde ser ativado.'));let refreshing=false;let hadController=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController&&!refreshing){refreshing=true;location.reload()}})}}catch(err){console.error(err);app.innerHTML=header()+`<main class="shell"><h1>Não foi possível abrir os dados.</h1><p>Verifique se o navegador permite armazenamento local e recarregue a página. Nenhum dado foi apagado.</p><button onclick="location.reload()">Tentar novamente</button></main>`}}
init();

window.visualViewport?.addEventListener('resize',()=>{let t=document.activeElement;if(t?.matches('input,textarea')&&window.visualViewport.height<window.innerHeight*.85)t.scrollIntoView({block:'center',behavior:'auto'})});
